<?php require 'faculty_bootstrap.php'; $title='Attendance'; $fid=(int)$_SESSION['user']['id']; $offering=(int)($_GET['offering']??0); $date=$_GET['date']??date('Y-m-d');
$q=$pdo->prepare("SELECT o.id,s.code,s.name,o.section,o.day_name,o.start_time,o.end_time FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.faculty_id=? ORDER BY s.code,o.section,o.day_name");$q->execute([$fid]);$classes=$q->fetchAll();if(!$offering&&$classes)$offering=(int)$classes[0]['id'];
$selected=null;$roster=[];$message='';
if($offering){$q=$pdo->prepare("SELECT o.*,s.code,s.name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.id=? AND o.faculty_id=?");$q->execute([$offering,$fid]);$selected=$q->fetch();if($selected){$r=$pdo->prepare("SELECT u.id,u.name,u.student_id,COALESCE(ar.status,'Present') status,COALESCE(ar.note,'') note FROM enrollments e JOIN users u ON u.id=e.student_id LEFT JOIN attendance_records ar ON ar.student_id=u.id AND ar.offering_id=e.offering_id AND ar.attendance_date=? WHERE e.offering_id=? AND e.status='approved' ORDER BY u.name");$r->execute([$date,$offering]);$roster=$r->fetchAll();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_attendance'){$off=(int)$_POST['offering_id'];$dt=$_POST['attendance_date']??date('Y-m-d');if($dt>date('Y-m-d')){$message='Attendance cannot be recorded for a future date.';}else{try{$pdo->beginTransaction();$check=$pdo->prepare("SELECT e.student_id FROM enrollments e JOIN subject_offerings o ON o.id=e.offering_id WHERE e.offering_id=? AND o.faculty_id=? AND e.status='approved'");$check->execute([$off,$fid]);$allowed=[];foreach($check as $x)$allowed[(int)$x['student_id']]=true;$ins=$pdo->prepare("INSERT INTO attendance_records(offering_id,student_id,attendance_date,status,note,recorded_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by)");foreach($_POST['status']??[] as $sid=>$st){$sid=(int)$sid;if(isset($allowed[$sid])&&in_array($st,['Present','Late','Absent','Excused'],true)){$ins->execute([$off,$sid,$dt,$st,trim($_POST['note'][$sid]??''),$fid]);}}$pdo->commit();$message='Attendance saved successfully.';notify_user($pdo,$fid,'Attendance saved','Attendance was updated for '.($selected['code']??'the class').' on '.date('M d, Y',strtotime($dt)).'.','Attendance');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message='Unable to save attendance: '.$e->getMessage();}}
}
require 'header.php'; faculty_flash_html(); ?><section class="section"><div class="section-intro"><div><span class="eyebrow">FACULTY</span><h2>Attendance</h2><p class="muted">Record attendance for your assigned classes.</p></div></div><?php if($message):?><div class="success"><?=e($message)?></div><?php endif;?><form class="filter-bar" method="get"><label>Class <select name="offering" onchange="this.form.submit()"><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$offering===$c['id']?'selected':''?>><?=e($c['code'].' · '.$c['section'])?></option><?php endforeach;?></select></label><label>Date <input type="date" name="date" value="<?=e($date)?>" max="<?=e(date('Y-m-d'))?>"></label><button class="btn">Load</button></form><?php if(!$selected):?><div class="info-box">No assigned class found.</div><?php else:?><div class="card-head"><div><h3><?=e($selected['code'])?> — <?=e($selected['name'])?></h3><p class="muted">Section <?=e($selected['section'])?> · <?=e($date)?></p></div></div><form method="post"><input type="hidden" name="action" value="save_attendance"><input type="hidden" name="offering_id" value="<?=$offering?>"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><div class="table-scroll"><table class="table"><tr><th>Student</th><th>ID</th><th>Status</th><th>Note</th></tr><?php foreach($roster as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['student_id']?:'—')?></td><td><select name="status[<?=$r['id']?>]"><?php foreach(['Present','Late','Absent','Excused'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></td><td><input name="note[<?=$r['id']?>]" value="<?=e($r['note'])?>" placeholder="Optional note"></td></tr><?php endforeach;?></table></div><button class="btn" style="margin-top:14px">Save Attendance</button></form><?php endif;?></section><?php require 'footer.php'; ?>
